/**
 * Package `defineConnection({ tools })` into a `node -e` stdio transport a
 * repo-less cloud VM can spawn.
 */
import { existsSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import * as esbuild from "esbuild";
import { toolInputJsonSchema, toolOutputJsonSchema } from "./json-schema.js";
function sibling(basename) {
    const dir = fileURLToPath(new URL(".", import.meta.url));
    const ts = join(dir, `${basename}.ts`);
    return existsSync(ts) ? ts : join(dir, `${basename}.js`);
}
const PINNED_ZOD = Symbol("inline-stdio-pinned-zod");
/**
 * Resolve every `zod` specifier (`zod`, `zod/v3`, `zod/v4`, ...) from this
 * package, so the bundle uses the zod copy the host uses. Resolution keeps
 * esbuild's conditions: an `import` gets the ESM build, which tree-shakes.
 * The CommonJS build of zod 4 does not, and the whole `node -e` script must
 * fit in one process argument (128 KiB on Linux).
 */
const pinZodPlugin = {
    name: "inline-stdio-pin-zod",
    setup(build) {
        const resolveDir = fileURLToPath(new URL(".", import.meta.url));
        build.onResolve({ filter: /^zod(?:\/.*)?$/ }, (args) => {
            if (args.pluginData === PINNED_ZOD) {
                return undefined;
            }
            return build.resolve(args.path, { kind: args.kind, resolveDir, pluginData: PINNED_ZOD });
        });
    },
};
function jsonSchemaCatalog(tools) {
    const catalog = {};
    for (const [name, tool] of Object.entries(tools)) {
        const outputSchema = toolOutputJsonSchema(tool.outputSchema);
        catalog[name] = {
            description: tool.description,
            inputSchema: toolInputJsonSchema(tool.inputSchema),
            outputSchema,
        };
    }
    return catalog;
}
export async function packageInlineStdioConnection(options) {
    const runtimePath = sibling("inline-stdio-mcp");
    const stubPath = sibling("inline-stdio-define-stub");
    const catalog = jsonSchemaCatalog(options.tools);
    const result = await esbuild.build({
        entryPoints: ["inline-stdio-entry"],
        bundle: true,
        write: false,
        platform: "node",
        format: "esm",
        target: "node22",
        minify: true,
        legalComments: "none",
        absWorkingDir: options.absWorkingDir,
        plugins: [
            pinZodPlugin,
            {
                name: "inline-stdio-entry",
                setup(build) {
                    build.onResolve({ filter: /^inline-stdio-entry$/ }, () => ({
                        path: "inline-stdio-entry",
                        namespace: "inline-stdio",
                    }));
                    build.onLoad({ filter: /.*/, namespace: "inline-stdio" }, () => ({
                        contents: `import definition from ${JSON.stringify(options.entryPath)};
import { serveInlineStdioMcp } from ${JSON.stringify(runtimePath)};
serveInlineStdioMcp(
  ${JSON.stringify(options.name)},
  definition,
  ${JSON.stringify(catalog)}
);
`,
                        resolveDir: dirname(options.entryPath),
                        loader: "ts",
                    }));
                },
            },
            {
                name: "inline-stdio-connection-stub",
                setup(build) {
                    build.onResolve({ filter: /^(?:@grok\/agent-sdk|@cursor\/(?:bdk|july))\/connections$/ }, () => ({
                        path: stubPath,
                    }));
                },
            },
        ],
    });
    const file = result.outputFiles?.[0];
    if (file === undefined) {
        throw new Error(`Failed to package inline stdio MCP connection "${options.name}": esbuild produced no output.`);
    }
    const source = file.text.replace(/^#!.*\r?\n/, "");
    if (source.trim() === "") {
        throw new Error(`Failed to package inline stdio MCP connection "${options.name}": empty bundle.`);
    }
    return {
        type: "stdio",
        command: "node",
        args: ["--input-type=module", "-e", source],
    };
}
